using System;
using System.IO;
using System.Linq;
using Assets.Script.DynamicCards;
using UnityEditor;
using UnityEditor.Animations;
using UnityEngine;
namespace LegacyGwent.LadyLakePremium.Editor {
// Bake authored beats onto the same material-property components and Animator clips as imported cards.
public static class LadyLakeProductionEffects {
const string Folder="Assets/Experiments/LadyLakePremium/Integration/Generated";
public static void Bake(GameObject environment){AddCatchBubbles(environment);var animator=environment.GetComponent<Animator>();if(animator==null||animator.runtimeAnimatorController==null)throw new Exception("Environment Animator missing");var glow=environment.transform.Find("SwordGlow");var sheen=environment.transform.Find("CausticSheen");if(glow==null||sheen==null)throw new Exception("Environment luminous surfaces missing");Directory.CreateDirectory(Folder);AssetDatabase.Refresh();AddDriver(environment.transform,"GlowAnimation",glow.GetComponent<Renderer>(),.10f);AddDriver(environment.transform,"SheenAnimation",sheen.GetComponent<Renderer>(),.26f);
var clips=animator.runtimeAnimatorController.animationClips;AnimationClip intro=null,loop=null;foreach(var source in clips.Distinct()){bool isLoop=source.name.IndexOf("Loop",StringComparison.OrdinalIgnoreCase)>=0;var clip=UnityEngine.Object.Instantiate(source);clip.name=isLoop?"EnvironmentLoop":"EnvironmentIntro";var g=new AnimationCurve();var c=new AnimationCurve();var scale=new AnimationCurve();for(int i=0;i<=360;i++){float t=i/30f;float value=Glow(t);g.AddKey(t,value);c.AddKey(t,.26f+.14f*(.5f+.5f*Mathf.Sin(t/12f*Mathf.PI*4)));scale.AddKey(t,Mathf.Lerp(.72f,1f,value));}AnimationUtility.SetEditorCurve(clip,EditorCurveBinding.FloatCurve("GlowAnimation",typeof(DynamicCardAnimatedMaterialProperty),"m_Float"),g);AnimationUtility.SetEditorCurve(clip,EditorCurveBinding.FloatCurve("SheenAnimation",typeof(DynamicCardAnimatedMaterialProperty),"m_Float"),c);foreach(string axis in new[]{"x","y","z"})AnimationUtility.SetEditorCurve(clip,EditorCurveBinding.FloatCurve("SwordGlow",typeof(Transform),"m_LocalScale."+axis),scale);string path=Folder+"/"+clip.name+".anim";var existing=AssetDatabase.LoadAssetAtPath<AnimationClip>(path);if(existing!=null){EditorUtility.CopySerialized(clip,existing);UnityEngine.Object.DestroyImmediate(clip);clip=existing;}else AssetDatabase.CreateAsset(clip,path);if(isLoop)loop=clip;else intro=clip;}
if(intro==null||loop==null)throw new Exception("Environment requires Intro and Loop");string cp=Folder+"/Environment.controller";var controller=AssetDatabase.LoadAssetAtPath<AnimatorController>(cp)??AnimatorController.CreateAnimatorControllerAtPath(cp);var sm=controller.layers[0].stateMachine;foreach(var s in sm.states)sm.RemoveState(s.state);var first=sm.AddState("Intro");first.motion=intro;var next=sm.AddState("Loop");next.motion=loop;sm.defaultState=first;var tr=first.AddTransition(next);tr.hasExitTime=true;tr.exitTime=1;tr.duration=0;tr.hasFixedDuration=true;animator.runtimeAnimatorController=controller;foreach(var component in environment.GetComponents<MonoBehaviour>())if(component!=null&&component.GetType().Name=="LadyLakeEnvironmentCycle")UnityEngine.Object.DestroyImmediate(component);EditorUtility.SetDirty(controller);AssetDatabase.SaveAssets();}
static void AddCatchBubbles(GameObject environment){
var source=environment.transform.Find("Bubbles");if(source==null)throw new Exception("Original bubble system missing");var go=UnityEngine.Object.Instantiate(source.gameObject,environment.transform,false);go.name="CatchBubbles";go.transform.localPosition=Vector3.zero;var ps=go.GetComponent<ParticleSystem>();ps.Stop(true,ParticleSystemStopBehavior.StopEmittingAndClear);var main=ps.main;main.loop=false;main.prewarm=false;main.playOnAwake=false;main.duration=1f;main.startLifetime=new ParticleSystem.MinMaxCurve(.45f,.85f);main.startSize=new ParticleSystem.MinMaxCurve(.025f,.07f);main.maxParticles=24;var emission=ps.emission;emission.rateOverTime=0;emission.SetBursts(new[]{new ParticleSystem.Burst(0f,(short)14)});var shape=ps.shape;shape.shapeType=ParticleSystemShapeType.Sphere;shape.radius=.1f;shape.scale=Vector3.one;var velocity=ps.velocityOverLifetime;velocity.x=new ParticleSystem.MinMaxCurve(-.13f,.13f);velocity.y=new ParticleSystem.MinMaxCurve(.22f,.45f);velocity.z=new ParticleSystem.MinMaxCurve(-.1f,.1f);
}
static void AddDriver(Transform root,string name,Renderer target,float initial){var go=new GameObject(name);go.transform.SetParent(root,false);var d=go.AddComponent<DynamicCardAnimatedMaterialProperty>();d.Type=2;d.Slot=0;d.Name="_AlphaMult";d.m_Float=initial;d.Targets=new[]{target};}
static float Glow(float t){if(t>=12)t=0;float value=.10f;float d=t-3.06f;if(d>0&&d<.85f)value+=.9f*(1-Mathf.Exp(-d/.028f))*Mathf.Exp(-d/.16f);d=t-3.2f;if(d>.1f&&d<1.4f)value+=.22f*Mathf.Exp(-(d-.1f)/.30f)*Mathf.Sin((d-.1f)*34);if(t>5.6f&&t<8.3f)value+=.52f*Mathf.SmoothStep(0,1,Mathf.Min(Mathf.Clamp01((t-5.6f)/.7f),Mathf.Clamp01((8.3f-t)/.45f)));if(t>=8.3f&&t<10.9f)value+=.16f*Mathf.Exp(-(t-8.3f)/.55f);return Mathf.Clamp01(value);}
}}
